"""Self-contained offline GLB viewer with eight real Blender render fallbacks."""
import base64
import json
from pathlib import Path

VIEWS=("front","front_3q","right","back_3q","back","left","top","bottom")

def make_viewer(root):
    root=Path(root)
    glb=base64.b64encode((root/"model.glb").read_bytes()).decode()
    images={v:"data:image/png;base64,"+base64.b64encode((root/(v+".png")).read_bytes()).decode() for v in VIEWS}
    spec=json.loads((root/"design.json").read_text())
    joints=[{"name":x["node"],"axis":[x["axis"][0],x["axis"][2],-x["axis"][1]],"range":x["range_deg"]} for x in spec.get("joint_checks",[])]
    html=HEAD+json.dumps({"glb":glb,"images":images,"joints":joints},separators=(",",":"))+SCRIPT
    (root/"viewer.html").write_text(html,encoding="utf-8")

